import itertools
feats={'1':np.ones_like(A),'A':A,'A2':A**2,'t':t,'tA':t*A,'t2':t**2,'t2A':t**2*A,'tA2':t*A**2,'lnA':np.log(A),'1/A':1/A,'t/A':t/A,'sqrtA':np.sqrt(A),'expt':np.exp(-t),'A3':A**3}
names=list(feats)
best=[]
for k in range(1,5):
    for c in itertools.combinations(names,k):
        X=np.column_stack([feats[n] for n in c])
        b,res,*_=np.linalg.lstsq(X,dA_dt,rcond=None)
        r=dA_dt-X@b
        nmse=np.mean(r**2)/np.var(dA_dt)
        best.append((nmse,c,b))
best.sort(key=lambda x:x[0])
for x in best[:10]: print(x)

